/// <summary>
/// METTransferOrderVoucherHelperClass has to help for get individual dimension values
/// </summary>
class METTransferOrderVoucherHelperClass
{
}

Method.Source:
    /// <summary>
    /// get the profit center dimension value
    /// </summary>
    /// <param name = "_recId">_recId</param>
    /// <returns>DisplayValue</returns>
    public static DimensionDisplayValue getProfitDimensionValue(InventSiteLockedDimensionValueSet _recId)
    {
        DimensionAttributeValueSet      dimensionAttributeValueSet;
        DimensionAttributeValueSetItem  dimensionAttributeValueSetItem;
        DimensionAttribute              dimensionAttribute;
        DimensionAttributeValue         dimensionAttributeValue;

        select firstonly RecId from dimensionAttributeValueSet
            where dimensionAttributeValueSet.RecId ==_recId
        join RecId,DisplayValue from dimensionAttributeValueSetItem
            where dimensionAttributeValueSetItem.DimensionAttributeValueSet == dimensionAttributeValueSet.RecId
        join RecId from dimensionAttributeValue
            where dimensionAttributeValue.RecId == dimensionAttributeValueSetItem.DimensionAttributeValue
        join RecId,Name from dimensionAttribute
            where dimensionAttribute.RecId == dimensionAttributeValue.DimensionAttribute
            &&  dimensionAttribute.Name == METConstants::profitCentre; 

        return dimensionAttributeValueSetItem.DisplayValue;

    }

    /// <summary>
    /// get the Individual dimension value
    /// </summary>
    /// <param name = "_attributeName">_attributeName</param>
    /// <param name = "_recId">_recId</param>
    /// <returns>DisplayValue</returns>
    public static DimensionDisplayValue getIndividualDimValues(Name _attributeName,LedgerDimensionBase _recId)
    {
        DimensionAttributeLevelValueView valueView;
        DimensionAttribute attribute;

        select firstonly DisplayValue from valueView
            where valueView.ValueCombinationRecId ==_recId
            join attribute
            where valueView.DimensionAttribute == attribute.RecId
            && attribute.Name ==_attributeName;

        return valueView.DisplayValue;
    }

    /// <summary>
    /// get the default dimension value
    /// </summary>
    /// <param name = "_generalJournalAccountEntry">_generalJournalAccountEntry</param>
    /// <returns>DefaultDimension</returns>
    public static InventSiteLockedDimensionValueSet getWarehouseDefaultDim(GeneralJournalAccountEntry _generalJournalAccountEntry)
    {
        GeneralJournalEntry     generalJournalEntry;
        InventTransferJour      inventTransferJour;
        InventTransferTable     inventTransferTable;
        InventLocation          inventLocation;

        select firstonly METDefaultDimension  from inventLocation
            join inventTransferTable
        where inventTransferTable.InventLocationIdTo == inventLocation.InventLocationId
            join inventTransferJour
        where inventTransferJour.TransferId == inventTransferTable.TransferId
            join generalJournalEntry
        where generalJournalEntry.SubledgerVoucher == inventTransferJour.VoucherId
            && generalJournalEntry.RecId == _generalJournalAccountEntry.GeneralJournalEntry;

        return inventLocation.METDefaultDimension;
    }

    /// <summary>
    /// get the ledger dimension value
    /// </summary>
    /// <param name = "convalue">convalue</param>
    /// <param name = "_mainAccountId">_mainAccountId</param>
    /// <returns>Ledger dimension</returns>
    public static DimensionDynamicAccount generateLedgerDimension(Container convalue,MainAccountNum _mainAccountId)
    {
        DimensionAttributeValueSetStorage valueSetStorage = new DimensionAttributeValueSetStorage();
        DimensionDefault defaultDim;
        int i;
        DimensionAttribute dimensionAttribute;
        DimensionAttributeValue dimensionAttributeValue;
        container conAttr =[METConstants::businessUnit, METConstants::costCenter, METConstants::itemGroup, METConstants::pillar, METConstants::profitCentre];
         
        str dimValue;

        for(i=1; i<= conlen(conAttr); i++)
        {
            dimensionAttribute = DimensionAttribute::findByName(conpeek(conAttr,i));
            if(dimensionAttribute.RecId == 0)
            {
                continue;
            }
            dimValue = conpeek(conValue,i);
            if(dimValue != METConstants::emptyString)
            {
                dimensionAttributeValue = dimensionAttributeValue::findByDimensionAttributeAndValue(dimensionAttribute,dimValue,false,true);
                valueSetStorage.addItem(dimensionAttributeValue);
            }
        }
        defaultDim = valueSetStorage.save();


        return LedgerDimensionFacade::serviceCreateLedgerDimension(
            LedgerDefaultAccountHelper::getDefaultAccountFromMainAccountRecId(
                MainAccount::findByMainAccountId(_mainAccountId).RecId),
            defaultDim);
    }
